/* CSS PART 1 OF 2 */

/* Design tokens */
:root {
  color-scheme: light;
  --color-forest: #243f32;
  --color-forest-deep: #192f26;
  --color-sage: #82947a;
  --color-sage-light: #e8ede3;
  --color-sun: #d9a94f;
  --color-cream: #f7f5ee;
  --color-paper: #fffefa;
  --color-earth: #82735d;
  --color-ink: #29332d;
  --color-muted: #68736b;
  --color-border: #dedfd5;

  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Trebuchet MS", Arial, sans-serif;

  --container: 1160px;
  --gutter: clamp(22px, 5vw, 76px);
  --header-height: 84px;

  --radius-small: 4px;
  --radius-medium: 12px;
  --radius-large: 22px;

  --shadow-soft: 0 12px 38px rgba(35, 55, 40, 0.09);
  --transition: 220ms ease;
}

/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

::selection {
  color: white;
  background: var(--color-forest);
}

/* Shared typography */
h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  color: var(--color-forest);
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

h1 {
  max-width: 850px;
  margin-bottom: 25px;
  font-size: clamp(3.1rem, 7.5vw, 6.5rem);
}

h2 {
  margin-bottom: 22px;
  font-size: clamp(2.4rem, 4.5vw, 4.1rem);
}

h3 {
  margin-bottom: 12px;
  font-size: 1.55rem;
}

p {
  color: var(--color-muted);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--color-earth);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 27px;
  height: 1px;
  background: var(--color-sun);
  content: "";
}

.section-intro {
  max-width: 620px;
  margin-bottom: 46px;
}

.section-intro p {
  max-width: 540px;
  font-size: 1.05rem;
  line-height: 1.85;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--color-forest);
  font-size: 0.85rem;
  font-weight: 700;
}

.text-link::after {
  content: "↗";
  transition: transform var(--transition);
}

.text-link:hover::after {
  transform: translate(3px, -3px);
}

/* Accessibility */
:focus-visible {
  outline: 3px solid var(--color-sun);
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  z-index: 1000;
  top: 12px;
  left: 12px;
  padding: 12px 18px;
  transform: translateY(-160%);
  background: white;
  color: var(--color-forest);
}

.skip-link:focus {
  transform: translateY(0);
}

/* Page layout */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  position: relative;
  padding-block: clamp(76px, 10vw, 132px);
}

.section--cream {
  background: var(--color-cream);
}

.section--sage {
  background: var(--color-sage-light);
}

.section-heading {
  max-width: 760px;
}

/* Header and navigation */
.site-header {
  position: relative;
  z-index: 20;
  height: var(--header-height);
  background: var(--color-paper);
  border-bottom: 1px solid rgba(41, 51, 45, 0.08);
}

.header-inner {
  display: flex;
  width: min(1320px, calc(100% - var(--gutter) * 1.3));
  height: 100%;
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 13px;
  color: var(--color-forest);
}

.brand img {
  width: auto;
  max-width: 62px;
  max-height: 57px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.brand-name {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.025em;
}

.brand-description {
  margin-top: 5px;
  color: var(--color-muted);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: clamp(20px, 3vw, 40px);
}

.main-nav a:not(.button) {
  position: relative;
  padding-block: 9px;
  color: var(--color-ink);
  font-size: 0.82rem;
  font-weight: 600;
  transition: color var(--transition);
}

.main-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 2px;
  left: 0;
  height: 1px;
  transform: scaleX(0);
  transform-origin: left;
  background: var(--color-sage);
  content: "";
  transition: transform var(--transition);
}

.main-nav a:not(.button):hover {
  color: var(--color-sage);
}

.main-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

/* Reusable buttons */
.button {
  display: inline-flex;
  min-height: 52px;
  padding: 0 25px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  cursor: pointer;
  font-size: 0.79rem;
  font-weight: 700;
  letter-spacing: 0.055em;
  text-align: center;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  transform: translateY(-2px);
}

.button--primary {
  background: var(--color-forest);
  color: white;
}

.button--primary:hover {
  background: var(--color-forest-deep);
}

.button--light {
  background: var(--color-paper);
  color: var(--color-forest);
}

.button--light:hover {
  background: var(--color-cream);
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.75);
  background: transparent;
  color: white;
}

.button--outline:hover {
  background: white;
  color: var(--color-forest);
}

.button-arrow {
  font-size: 1.1rem;
  line-height: 1;
}

/* Full-bleed hero */
.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - var(--header-height)));
  overflow: hidden;
  align-items: center;
  background: var(--color-forest-deep);
  color: white;
}

.hero-media {
  position: absolute;
  z-index: 0;
  inset: 0;
}

.hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 52%;
}

.hero-media::after {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(18, 39, 29, 0.88) 0%,
      rgba(18, 39, 29, 0.69) 42%,
      rgba(18, 39, 29, 0.15) 100%
    ),
    linear-gradient(
      0deg,
      rgba(18, 39, 29, 0.32),
      transparent 45%
    );
  content: "";
}

.hero-content {
  position: relative;
  z-index: 1;
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin: 0 auto;
  padding-block: 105px 125px;
}

.hero .eyebrow {
  color: #e8d6a8;
}

.hero h1 {
  max-width: 780px;
  color: white;
}

.hero-description {
  max-width: 540px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, 0.88);
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.85;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-note {
  display: flex;
  margin-top: 48px;
  align-items: center;
  gap: 13px;
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.hero-note::before {
  width: 32px;
  height: 1px;
  background: var(--color-sun);
  content: "";
}

/* Family-owned introduction */
.intro-section {
  padding-block: clamp(90px, 11vw, 145px);
}

.intro-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: start;
  gap: clamp(45px, 9vw, 125px);
}

.intro-heading {
  position: sticky;
  top: 40px;
}

.intro-heading h2 {
  max-width: 480px;
}

.intro-copy {
  max-width: 590px;
  padding-top: 12px;
}

.intro-copy p {
  font-size: 1.04rem;
  line-height: 1.95;
}

.intro-copy p + p {
  margin-top: 23px;
}

.intro-highlight {
  margin-top: 36px;
  padding: 22px 25px;
  border-left: 3px solid var(--color-sun);
  background: var(--color-cream);
  color: var(--color-forest);
  font-family: var(--font-display);
  font-size: 1.25rem;
  line-height: 1.5;
}

/* Landscaping and irrigation services */
.services-section {
  overflow: hidden;
}

.services-layout {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: clamp(45px, 8vw, 105px);
  align-items: start;
}

.services-heading {
  position: sticky;
  top: 40px;
}

.services-heading h2 {
  max-width: 460px;
}

.services-heading p {
  max-width: 390px;
  line-height: 1.85;
}

.services-list {
  border-top: 1px solid var(--color-border);
}

.service-item {
  display: grid;
  grid-template-columns: 55px 1fr;
  gap: 22px;
  padding: 27px 0;
  border-bottom: 1px solid var(--color-border);
}

.service-number {
  padding-top: 4px;
  color: var(--color-earth);
  font-family: var(--font-display);
  font-size: 1.1rem;
}

.service-item h3 {
  margin-bottom: 7px;
}

.service-item p {
  max-width: 480px;
  margin-bottom: 0;
  font-size: 0.93rem;
  line-height: 1.75;
}

/* Local sourcing and quality */
.local-section {
  position: relative;
  overflow: hidden;
  background: var(--color-forest);
  color: white;
}

.local-layout {
  display: grid;
  grid-template-columns: 1fr 0.8fr;
  align-items: center;
  gap: clamp(45px, 8vw, 110px);
}

.local-content h2 {
  max-width: 620px;
  color: white;
}

.local-content p {
  max-width: 550px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 1.02rem;
  line-height: 1.9;
}

.local-content .eyebrow {
  color: #e6c98f;
}

.local-values {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
}

.local-value {
  padding: 25px 18px 25px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.22);
}

.local-value h3 {
  margin-bottom: 8px;
  color: white;
  font-size: 1.25rem;
}

.local-value p {
  margin-bottom: 0;
  font-size: 0.85rem;
  line-height: 1.65;
}

.local-mark {
  color: var(--color-sun);
  font-family: var(--font-display);
  font-size: 1.8rem;
  line-height: 1;
}

/* Free estimate conversion section */
.estimate-section {
  padding-block: clamp(85px, 10vw, 125px);
  background: var(--color-cream);
}

.estimate-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
}

.estimate-copy {
  max-width: 680px;
}

.estimate-copy h2 {
  margin-bottom: 15px;
}

.estimate-copy p {
  max-width: 570px;
  margin-bottom: 0;
  font-size: 1rem;
  line-height: 1.85;
}

.estimate-action {
  flex-shrink: 0;
}
