/* CSS PART 2 OF 2 */

/* Contact and conversion */
.contact-section {
  padding-block: clamp(85px, 10vw, 130px);
  background: var(--color-paper);
}

.contact-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: clamp(45px, 9vw, 120px);
  align-items: start;
}

.contact-copy {
  max-width: 430px;
}

.contact-copy h2 {
  margin-bottom: 20px;
}

.contact-copy p {
  line-height: 1.85;
}

.contact-details {
  display: grid;
  gap: 18px;
  margin-top: 35px;
}

.contact-detail {
  padding-top: 17px;
  border-top: 1px solid var(--color-border);
}

.contact-detail strong {
  display: block;
  margin-bottom: 4px;
  color: var(--color-forest);
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.contact-detail span {
  color: var(--color-muted);
  font-size: 0.93rem;
}

.contact-form {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
  padding: clamp(24px, 4vw, 44px);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-medium);
  background: var(--color-cream);
  box-shadow: var(--shadow-soft);
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--color-forest);
  font-size: 0.8rem;
  font-weight: 700;
}

.form-field input,
.form-field textarea,
.form-field select {
  width: 100%;
  min-width: 0;
  min-height: 50px;
  padding: 12px 14px;
  border: 1px solid #d4d8ce;
  border-radius: var(--radius-small);
  background: white;
  color: var(--color-ink);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input:focus,
.form-field textarea:focus,
.form-field select:focus {
  border-color: var(--color-sage);
  box-shadow: 0 0 0 3px rgba(130, 148, 122, 0.18);
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #879087;
}

.contact-form .button {
  justify-self: start;
}

/* Footer */
.site-footer {
  padding: 54px 0 25px;
  background: var(--color-forest-deep);
  color: white;
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 35px;
  padding-bottom: 38px;
}

.footer-brand {
  color: white;
}

.footer-brand .brand-description {
  color: rgba(255, 255, 255, 0.65);
}

.footer-message {
  max-width: 380px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.9rem;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.75rem;
}

.footer-bottom a {
  color: white;
  text-decoration: underline;
  text-underline-offset: 4px;
}

/* Accessible mobile menu control */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  padding: 0;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--color-forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* Responsive layouts */
@media (max-width: 900px) {
  :root {
    --header-height: 76px;
  }

  .main-nav {
    gap: 16px;
  }

  .main-nav a:not(.button) {
    font-size: 0.76rem;
  }

  .intro-layout,
  .services-layout {
    grid-template-columns: 1fr 1fr;
    gap: 42px;
  }

  .local-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .contact-layout {
    grid-template-columns: 1fr 1.2fr;
    gap: 35px;
  }

  .estimate-inner {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 680px) {
  :root {
    --gutter: 22px;
    --header-height: 72px;
  }

  html {
    scroll-padding-top: 85px;
  }

  body {
    font-size: 15px;
  }

  .site-header {
    position: relative;
  }

  .header-inner {
    width: calc(100% - 36px);
    gap: 12px;
  }

  .brand {
    gap: 9px;
  }

  .brand img {
    max-width: 47px;
    max-height: 47px;
  }

  .brand-name {
    font-size: 1.05rem;
  }

  .brand-description {
    font-size: 0.54rem;
  }

  .menu-toggle {
    display: flex;
    flex-shrink: 0;
  }

  .main-nav {
    position: absolute;
    z-index: 30;
    top: 100%;
    right: 0;
    left: 0;
    display: none;
    max-height: calc(100svh - var(--header-height));
    overflow-y: auto;
    padding: 18px var(--gutter) 24px;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    border-top: 1px solid var(--color-border);
    background: var(--color-paper);
    box-shadow: var(--shadow-soft);
  }

  .main-nav.is-open {
    display: flex;
  }

  .main-nav a:not(.button) {
    display: block;
    width: 100%;
    padding: 14px 4px;
    border-bottom: 1px solid var(--color-border);
    font-size: 0.9rem;
  }

  .main-nav a:not(.button)::after {
    display: none;
  }

  .main-nav .button {
    width: 100%;
    margin-top: 16px;
  }

  .section {
    padding-block: 76px;
  }

  h1 {
    font-size: clamp(3rem, 13vw, 4.5rem);
  }

  h2 {
    font-size: clamp(2.35rem, 10vw, 3.3rem);
  }

  .section-intro {
    margin-bottom: 34px;
  }

  .section-intro p {
    font-size: 0.96rem;
  }

  .hero {
    min-height: 690px;
    min-height: min(760px, calc(100svh - var(--header-height)));
    align-items: flex-end;
  }

  .hero-media img {
    object-position: 58% center;
  }

  .hero-media::after {
    background:
      linear-gradient(
        0deg,
        rgba(18, 39, 29, 0.94) 0%,
        rgba(18, 39, 29, 0.75) 48%,
        rgba(18, 39, 29, 0.24) 100%
      );
  }

  .hero-content {
    padding-top: 115px;
    padding-bottom: 65px;
  }

  .hero-description {
    font-size: 1rem;
  }

  .hero-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-note {
    margin-top: 30px;
    font-size: 0.66rem;
  }

  .intro-layout,
  .services-layout {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .intro-heading,
  .services-heading {
    position: static;
  }

  .intro-copy {
    padding-top: 0;
  }

  .intro-copy p {
    font-size: 0.97rem;
  }

  .intro-highlight {
    margin-top: 25px;
    padding: 19px;
    font-size: 1.12rem;
  }

  .service-item {
    grid-template-columns: 37px 1fr;
    gap: 13px;
    padding: 22px 0;
  }

  .service-item h3 {
    font-size: 1.35rem;
  }

  .local-layout {
    gap: 28px;
  }

  .local-values {
    grid-template-columns: 1fr 1fr;
  }

  .local-value {
    padding: 20px 12px 20px 0;
  }

  .local-value h3 {
    font-size: 1.1rem;
  }

  .estimate-inner {
    gap: 27px;
  }

  .estimate-action,
  .estimate-action .button {
    width: 100%;
  }

  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .contact-details {
    grid-template-columns: 1fr 1fr;
    gap: 15px;
  }

  .contact-form {
    grid-template-columns: 1fr;
    gap: 18px;
    padding: 22px;
  }

  .form-field--full {
    grid-column: auto;
  }

  .contact-form .button {
    width: 100%;
  }

  .footer-main {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
